import{_ as t,l as n,o as e,c as i,v as o,p as s,x as l,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"全球失衡","description":"","frontmatter":{"title":"全球失衡","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/global-imbalances.md","filePath":"econ/global-imbalances.md","lastUpdated":1789023840000}'),h={name:"econ/global-imbalances.md"};function A(E,a,u,f,B,_){const r=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="全球失衡" tabindex="-1">全球失衡 <a class="header-anchor" href="#全球失衡" aria-label="Permalink to &quot;全球失衡&quot;">​</a></h1><div class="epigraph"><p>资本在 2000 年代净流向已经资本丰裕的美国，而不是 Lucas 的穷国；要把这句话写成储蓄过剩、储备需求与安全资产供给，而不是再骂一次双赤字会计。</p><footer>—— Bernanke, The Global Saving Glut, 2005；Obstfeld and Rogoff 全球失衡与汇率；Caballero, Farhi and Gourinchas 安全资产</footer></div><p><a href="/econ/lucas-paradox">上一课</a>问为何资本不南流。本课缺口是方向反了：新兴亚洲与石油出口国的顺差对着美英逆差，「上流」。外汇干预与储备下一课把官方流量拆出来。本课钉失衡的宏观叙事，不重写<a href="/econ/twin-deficits">双赤字</a>恒等。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(CA\\equiv S-I\\) 对每一国成立。全球加总 \\(\\sum CA=0\\)（忽略统计误差）。美国 \\(CA\\lt 0\\) 必有别处 \\(CA\\gt 0\\)。Bernanke 储蓄过剩：新兴市场储蓄升、投资未同步，资本流出。另一侧：美国投资（住房）与财政。Obstfeld–Rogoff：要有相对价格（\\(q\\)、可贸易）调整才能收口，软着陆 vs 美元骤贬。Caballero–Farhi–Gourinchas：世界缺安全资产，美国生产国债与 AAA，资本为保险而上流。缺口是：三条叙事对象不同（储蓄、相对价格、资产供给），不要合成一句「美国挥霍」。</p><p><span class="marginnote">Gourinchas–Rey 的「过分特权」：美国对外资产负债的组成使它赚取稳定费。失衡不只是货物，也是风险分担——后课国际风险分担会接。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分解：私人 \\(S-I\\) vs 官方储备积累。2000 年代亚洲储备猛增，使「私人 Lucas」与「官方上流」分叉——下一课干预。跨期：逆差可以是最优（生产率预期、人口），也可以是泡沫（住房）。计量：不能把美国 \\(CA\\) 对财政做因果而不管全球 \\(S\\)。本课机制，不报新弹性。</p>',8)),(e(),s(p,null,{default:l(()=>[c(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUM%5B%22%E5%85%A8%E7%90%83%20%CE%A3%20CA%20%3D%200%22%5D%20--%3E%20US%5B%22%E7%BE%8E%E5%9B%BD%E9%80%86%E5%B7%AE%22%5D%0A%20%20GLUT%5B%22%E6%96%B0%E5%85%B4%E5%82%A8%E8%93%84%20%2F%20%E5%82%A8%E5%A4%87%22%5D%20--%3E%20US%0A%20%20SAFE%5B%22%E5%AE%89%E5%85%A8%E8%B5%84%E4%BA%A7%E9%9C%80%E6%B1%82%22%5D%20--%3E%20US%0A%20%20Q%5B%22q%20%E8%B0%83%E6%95%B4%22%5D%20--%3E%20CLOSE%5B%22%E6%94%B6%E5%8F%A3%E8%A6%81%E7%9B%B8%E5%AF%B9%E4%BB%B7%E6%A0%BC%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与贸易课：中国冲击是劳动市场；中国顺差是账户。两者相关不必同一识别。价值链使双边货物顺差夸大 VA，但美国总 \\(CA\\) 仍是国民账户。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制候选。储蓄过剩：预防性储蓄、人口、金融压抑使新兴 \\(S\\) 高。投资不足：危机后亚洲 \\(I\\) 谨慎。安全资产：本地债市场浅（原罪），官方与私人都买美债。美国供给：财政赤字与住房证券化增加安全（或看似安全）资产。2008 年证明部分 AAA 不是安全，失衡的资产侧改写——后课危机。</p><p>条款：美元实际汇率在收口时要贬（Obstfeld–Rogoff）。若工资粘、原罪，贬值路径不是免费，主干已有。本课不重推超调。</p><p><span class="marginnote">「失衡」不是会计错误。它是可持续性判断：净外资产路径、估值效应、突然停止风险。可持续可以伴随大额逆差（高增长债务人）。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不预测某一年美元崩溃。不把储蓄过剩写成对 Bernanke 的人格评价。下一课官方储备与冲销，把「亚洲储蓄」里的央行部分拆开。不要用量化栏的外汇微观结构解释全球 \\(CA\\)。Lucas 悖论仍在：私人资本可以怕制度，官方可以买美债——两层流。</p><p>后课默认：全球加总为零；上流需要储蓄、安全资产或泡沫叙事之一；收口要 \\(q\\) 与吸收。双赤字是部门展开，不是全球格局的充分统计。储备下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>全球 \\(\\sum CA=0\\)；美国逆差对应别处顺差。</li><li>储蓄过剩、条款调整、安全资产三条叙事要分开。</li><li>官方储备使「私人南流缺失」与「官方上流」并存。</li><li>可持续性是 NFA 路径，不是道德评分。</li><li>出处：Bernanke 2005；Obstfeld and Rogoff；Caballero, Farhi and Gourinchas；Gourinchas and Rey。</li></ul>',10))])}const C=t(h,[["render",A]]);export{b as __pageData,C as default};
